function wheelList(){
  var out=[], i, n;
  for(i=0;i<WHEEL_ORDER.length;i++){ n=wheelHave(WHEEL_ORDER[i]); if(n>0) out.push({k:WHEEL_ORDER[i],n:n}); }
  return out;
}

